import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"两阶段锁","description":"","frontmatter":{"title":"两阶段锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/two-pl.md","filePath":"cs/two-pl.md","lastUpdated":1789023840000}'),h={name:"cs/two-pl.md"};function E(_,a,A,P,m,f){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="两阶段锁" tabindex="-1">两阶段锁 <a class="header-anchor" href="#两阶段锁" aria-label="Permalink to &quot;两阶段锁&quot;">​</a></h1><div class="epigraph"><p>先只加锁、后只放锁；增长阶段结束前不释放，调度就进不了冲突环。</p><footer>—— 据 Eswaran et al., 1976；Bernstein 对 2PL 与严格 2PL 的整理</footer></div><p><a href="/cs/rw-wr-ww">上一课</a>用冲突图定义合法交错。本课不重图画环。缺口是：运行时没有全局图可画完再执行，必须用锁协议<strong>只产生</strong>无环调度。两阶段锁（2PL）把每个事务切成增长与收缩；严格 2PL 把写锁留到提交，顺带挡住脏读与级联回滚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>冲突可串行是事后判定。引擎需要可局部检查的规则：读前加 S、写前加 X，冲突锁互斥。若锁可以边放边再申请，仍可能环。缺口不是<a href="/cs/lock-irq">锁与关中断</a>的自旋实现，而是事务级的<strong>阶段</strong>：增长期只申请，收缩期只释放。一旦进入收缩，不再申请，则 2PL 调度冲突可串行。</p><p><span class="marginnote">严格 2PL：所有 X 锁持有到 commit/abort。这比基本 2PL 更强，换可恢复、避免级联。实践默认这一档，而不是「一写完就放 X」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>锁管理器按数据项（页、行、谓词）登记。兼容矩阵：S 与 S 兼容，X 与一切冲突。等待或立刻拒绝（后者配合死锁预防）。本课不展开多粒度意向锁的全部 IS/IX 表，只承认粒度为了少锁项；粒度太粗会误冲突。</p>',8)),(e(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GROW%5B%22%E5%A2%9E%E9%95%BF%3A%20%E5%8F%AA%E5%8A%A0%E9%94%81%22%5D%20--%3E%20POINT%5B%22%E9%94%81%E7%82%B9%22%5D%0A%20%20POINT%20--%3E%20SHRINK%5B%22%E6%94%B6%E7%BC%A9%3A%20%E5%8F%AA%E6%94%BE%E9%94%81%22%5D%0A%20%20GROW%20--%3E%20ST%5B%22%E4%B8%A5%E6%A0%BC%3A%20X%20%E7%95%99%E5%88%B0%E6%8F%90%E4%BA%A4%22%5D%0A%20%20ST%20--%3E%20MVCC%5B%22%E5%90%8E%E8%AF%BE%3A%20MVCC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锁点（所有锁已拿到的时刻）给出一个串行序：按锁点排序与冲突图拓扑一致。这把隔离落实成等待。代价是阻塞与死锁——<a href="/cs/db-deadlock">库内死锁</a>再收。读多写少时，读锁互相放行；写密集时队列变长。这与操作系统临界区同一互斥直觉，对象是数据项而非一段内核代码。</p><p>锁点给出的串行序是冲突等价序，不必等于墙钟提交序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2PL 不管持久化：没日志仍会丢提交。也不消除幻象，除非锁住谓词或间隙。本课不把 SI、SSI 当 2PL 的一种；那是版本与图的另一条实现。锁升级（行到表）是启发式，可能制造意外阻塞。</p><p>读写锁与更新锁（U）是兼容矩阵的加密，用来避免升级死锁，不改变两阶段。后课默认：谈到锁隔离，默认严格 2PL 可给出冲突可串行且可恢复；读多时可用版本减少读阻塞。</p><p>锁的粒度越细，并发越高、死锁与内存越贵。意向锁把多粒度收成可组合的矩阵，本课只要求知道有这一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>收缩阶段若提前放 X，脏读可以发生；严格 2PL 用提交当锁点。</p></li><li><p>后课 MVCC 用版本换掉读锁，写写仍要协议。</p></li><li><p>可串行是规格；2PL 是「只加后放」的运行时协议。</p></li><li><p>严格 2PL 把 X 留到提交，服务可恢复。</p></li><li><p>读阻塞与写锁冲突的另一条路，是 MVCC。</p></li><li><p>出处：Eswaran et al., 1976；Bernstein, Hadzilacos and Goodman。</p></li></ul>',9))])}const S=l(h,[["render",E]]);export{B as __pageData,S as default};
